+  let mockDb: any;
+
+  const createMockFailurePattern = (overrides: Partial<FailurePattern> = {}): FailurePattern => ({
+    id: 'pattern-1',
+    taskType: 'coding',
+    taskCategory: 'testing',
+    errorPattern: 'connection refused',
+    occurrenceCount: 5,
+    successRate: 0.8,
